# Display name to file stem, erroring with the known names when one is wrong
def stem_of(ab):
    if ab in name_to_stem: return name_to_stem[ab]
    raise KeyError(f"unknown antibody {ab!r}; known: {sorted(name_to_stem)}")

# Kabat label to site index, in site order
def site_labels(ab):
    m = pd.read_csv(f"{data_dir}/{stem_of(ab)}_meta.csv")
    m = m.assign(idx=m["site"].str.replace("site_","",regex=False).astype(int)).sort_values("idx")
    return {f"{r.germline_aa}{r.kabat_position}{r.mature_aa}": r.idx for r in m.itertuples()}

# Site indices for the requested labels, erroring with the real options when one is wrong
def resolve_sites(ab, wanted):
    n2s = site_labels(ab)
    bad = [s for s in wanted if s not in n2s]
    if bad:
        raise KeyError(f"{ab}: no site {bad}; available are {list(n2s)}")
    return [n2s[s] for s in wanted]

# Inferred landscape table for one antibody and antigen
def df_all(ab, ag):
    return pd.read_csv(f"{data_dir}/{stem_of(ab)}_{ag}_BEST_df_all.csv").drop_duplicates("genotype_tokens")

# One row per variant measured against both antigens, replicate-averaged, plus its token
def variant_xy(ab):
    k = pd.read_csv(f"{data_dir}/{stem_of(ab)}_kds.csv")
    k["tok"] = k[sites].agg("".join, axis=1)
    def avg(ag):
        d = k[k.antigen == ag]
        return d.groupby("id", as_index=False).agg(v=("nlog10_Kd","mean"), tok=("tok","first"))
    y = avg(antigens[0]).rename(columns={"v":"y"})
    x = avg(antigens[1]).rename(columns={"v":"x"})
    return y.merge(x[["id","x"]], on="id")

# Every subset of the selected sites, empty first then by size
def subsets(labels):
    return [tuple(c) for r in range(len(labels)+1) for c in itertools.combinations(labels, r)]

# Colors for n subsets: the four-color ramp at four, the full eight at eight, else cycle
def palette_for(n):
    if n == len(bg_hex4): return list(bg_hex4)
    if n == len(bg_hex8): return list(bg_hex8)
    return [bg_hex8[i % len(bg_hex8)] for i in range(n)]
